layers.css:
.cc{position:absolute;inset:0;background:radial-gradient(120% 80% at 50% 42%,#2c1e17,#100b09 70%)}
.num{position:absolute;left:0;right:0;top:300px;text-align:center;font:400 1100px/1 'Russo One';color:rgba(247,236,222,calc(.04 + .1*var(--e)));transform:translateY(calc((1 - var(--e))*80px)) scale(calc(1.06 - .06*var(--e)))}
.dia{position:absolute;left:450px;top:790px;width:180px;height:180px;border:8px solid #F7ECDE;background:#C8321E;box-shadow:0 0 70px rgba(230,80,50,.75),0 30px 60px rgba(0,0,0,.6);transform:rotate(45deg) scale(min(1,calc(.2 + var(--e)*1.4)))}
.dia span{position:absolute;inset:0;display:grid;place-items:center;transform:rotate(-45deg);font:400 110px 'Russo One';color:#F7ECDE}
.lab{position:absolute;left:0;right:0;top:1090px;text-align:center;font:italic 500 96px 'FrauncesV';color:#F7ECDE;letter-spacing:-.01em;opacity:clamp(0,calc(var(--p)*5 - 1.4),1);transform:translateY(calc((1 - clamp(0,calc(var(--p)*4 - 1),1))*30px))}

.ui{position:absolute;left:60px;top:230px;width:780px;transform:translateY(calc((1 - var(--e))*-50px)) rotate(-3deg);opacity:min(1,calc(var(--t)*7))}
.pl{display:flex;align-items:center;gap:22px;padding:34px 40px;border-radius:38px;background:rgba(18,12,10,.88);box-shadow:0 26px 60px rgba(0,0,0,.45),inset 0 0 0 2px rgba(247,236,222,.18);font:700 62px Manrope;color:#F7ECDE}
.pl b{width:100px;height:100px;border-radius:50%;display:grid;place-items:center;background:#C8321E;font-size:44px}
.pl em{flex:1;height:10px;border-radius:5px;background:linear-gradient(90deg,#C8321E calc(var(--p)*100%),rgba(247,236,222,.2) 0)}
.ch{margin:22px 0 0 120px;display:inline-flex;align-items:center;gap:18px;padding:22px 36px;border-radius:999px;background:rgba(247,236,222,.95);font:800 58px Manrope;color:#2a1a14;box-shadow:0 20px 44px rgba(0,0,0,.35);opacity:clamp(0,calc((var(--t) - .9)*6),1);transform:scale(calc(.8 + .2*clamp(0,calc((var(--t) - .9)*5),1)))}
.ch span{text-decoration:line-through;text-decoration-color:#C8321E;text-decoration-thickness:6px}

